-- 0143: the five older government rows (VG:*) rooted in the lexicons. Each gets display_json.sources (book, block id,
-- page, short quote — for the backlink); the screen shows the plain English only (display_json.plain_en).
-- Fixes: كَتَبَ لِ "as their share" is in no book — al-Rāghib reads لَنا as "for us, a favour" against عَلَينا, so
-- "to decree something for someone, for their good"; كَتَبَ مَعَ — only al-Rāghib comments: «اجعلنا في زمرتهم», so
-- "to place among, to count with" (the "enrol in a list" sense of the books is Form VIII اكتتب, without مع).
-- Note: VG:كتب:I:لـ's old refs ("Rāghib Muf.424", "mir:322") are Mir's idioms book / a wrong page; kept as ingested.
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "lane_lexicon", "block_id": "blk_lane_097e59301c780e4f", "page": 2590, "quote": "He (God) prescribed, appointed, or ordained, and made obligatory … كُتِبَ عَلَيْكُمُ الصِّيَامُ"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_ff685f977a7ac053", "page": 699, "quote": "[وكتبنا عليهم فيها] أي: أوجبنا وفرضنا، وكذلك قوله: كُتِبَ عَلَيْكُمْ"}, {"source": "zamakhshari_asas_balagha", "block_id": "blk_asb_ktb_p4", "page": null, "quote": "ومن المجاز: كتب عليه كذا: قُضي عليه … وكتب على عباده الطاعة"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_a98d2ea97ab97a88", "page": 698, "quote": "كتب عليكم الصيام؛ معناه: فُرض"}]')) WHERE id = 'VG:كتب:I:على';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "raghib_mufradat", "block_id": "blk_mfr_f658124b17f4254a", "page": 699, "quote": "[ما كتب الله لنا] يعني: ما قدّره وقضاه، وذكر «لنا» ولم يقل «علينا»"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_934efdee292ec949", "page": 699, "quote": "تنبيها أنّ كلّ ما يصيبنا نعدّه نعمة لنا، ولا نعدّه نقمة علينا"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_a1f427fd32d52c66", "page": 699, "quote": "[كتب الله لكم] … يعود عليهم بنفع عاجل وآجل، فيكون ذلك لهم لا عليهم"}, {"source": "zamakhshari_asas_balagha", "block_id": "blk_asb_ktb_p4", "page": null, "quote": "وكتب الله الأجل والرزق … وهذا كتاب الله: قدره"}]'), '$.plain_en', 'to decree something for someone, for their good') WHERE id = 'VG:كتب:I:لـ';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "raghib_mufradat", "block_id": "blk_mfr_1fc34abd03346b30", "page": 699, "quote": "وقوله: أُولئِكَ كَتَبَ فِي قُلُوبِهِمُ الْإِيمانَ"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_aa94ca778b470433", "page": 699, "quote": "فإشارة منه إلى أنهم بخلاف من وصفهم بقوله: … أَغْفَلْنا قَلْبَهُ"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_165e9b1503036d02", "page": 699, "quote": "أغفلت الكتاب: إذا جعلته خاليا من الكتابة ومن الإعجام"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_984f11944d57b162", "page": 699, "quote": "ويعبّر عن الإثبات والتّقدير والإيجاب والفرض والعزم بالكتابة"}]')) WHERE id = 'VG:كتب:I:في';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "raghib_mufradat", "block_id": "blk_mfr_fcdcab59ebaa4639", "page": 699, "quote": "[فاكتبنا مع الشاهدين] أي: اجعلنا في زمرتهم"}, {"source": "ibn_manzur_lisan_arab", "block_id": "blk_lsn_0560e7c741b730f8", "page": 698, "quote": "اكتتبت في غزوة كذا وكذا؛ أي كتبت اسمي في جملة الغزاة — Form VIII, no مع"}, {"source": "lane_lexicon", "block_id": "blk_lane_08d8920bc2fc7381", "page": 2590, "quote": "I wrote down my name in the list of the soldiers of such an expedition"}]'), '$.plain_en', 'to place among, to count with') WHERE id = 'VG:كتب:I:مع';
UPDATE ar_ling_root_lemma_tadiya SET display_json = json_set(coalesce(display_json, '{}'), '$.sources', json('[{"source": "raghib_mufradat", "block_id": "blk_mfr_495f43b2607331c2", "page": 799, "quote": "وإنزال الله تعالى نعمه ونقمه على الخلق … أَنْزَلَ عَلى عَبْدِهِ الْكِتابَ"}, {"source": "zabidi_taj_arus", "block_id": "blk_taj_9305c0f0c8aa70ee", "page": 478, "quote": "ما وصل من الملأ الأعلى بلا واسطة تعديته بعلى المختص بالعلو أولى"}, {"source": "raghib_mufradat", "block_id": "blk_mfr_c58dde854b5fd680", "page": 799, "quote": "التنزيل يختص بالموضع الذي يشير إليه إنزاله مفرّقا، ومرّة بعد أخرى"}, {"source": "ibn_durayd_jamharat_lugha", "block_id": "blk_jmhr_nzl_p4", "page": 827, "quote": "وأنزل الله عز وجل الكتاب إنزالا ونزّله تنزيلا شيئا بعد شيء"}]')) WHERE id = 'VG:نزل:II';
